ARROW = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>'

def cta(text='Как попасть в тест', klass=''):
    return f'<a class="cta {klass}" href="#invite">{text} {ARROW}</a>'

def sources(style=''):
    return f'''<div class="sources-picker {style}" role="group" aria-label="Источник в примере комнаты"><button type="button" data-source="YouTube" aria-pressed="true">YouTube</button><button type="button" data-source="Telegram" aria-pressed="false">Telegram</button><button type="button" data-source="VK Видео" aria-pressed="false">VK Видео</button><button type="button" data-source="Другие ссылки" aria-pressed="false">Другие ссылки</button></div>'''

def photo(slug, klass='', alt='Пейзаж для демонстрации совместного просмотра'):
    return f'<img class="{klass}" src="__ASSETS__brands/{slug}.jpg" alt="{alt}" width="1440" height="960" fetchpriority="high">'

def player(slug, klass='', title='Место, где хочется оказаться'):
    return f'''<div class="video-preview {klass}" id="preview">{photo(slug)}<div class="video-shade"></div><div class="video-top"><span>Демо комнаты</span><span data-source-label>YouTube</span></div><div class="video-caption"><p class="preview-title">{title}</p><span>Пример видео · ваша компания</span></div><div class="video-controls"><button type="button" data-demo-play aria-label="Запустить демонстрацию" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 11 7-11 7Z" fill="currentColor"/></svg></button><span data-clock>00:00</span><input type="range" min="0" max="180" value="0" data-demo-seek aria-label="Позиция в демонстрации"><span>03:00</span></div></div>'''

def demo_note():
    return '<p class="demo-note">Интерактивный пример интерфейса. Видео не воспроизводится.</p>'

def faq(name):
    titles = {'Линкрум':'О Линкруме.<br>По делу.','Титры':'За пределами<br>титров.','Волна':'Прежде чем<br>подключиться.','Кадр':'За пределами<br>кадра.','Плед':'Пока греется чай,<br>пара ответов.','Синк':'Сверим<br>ожидания.','Дубль':'До нашей<br>первой встречи.','Комната':'Перед тем,<br>как войти.','Кружок':'Что обсуждают<br>в кружке.','Смотрим':'Перед тем,<br>как нажать play.'}
    return f'''<div class="questions" id="questions"><h2>{titles[name]}</h2><div><details><summary>Что можно будет смотреть?</summary><p>В закрытом тесте проверяем просмотр по ссылкам из YouTube, Telegram, VK Видео и других видеоплатформ. Доступность зависит от источника и доступа к оригиналу. Собственного каталога фильмов у {escape(name)} нет.</p></details><details><summary>Почему нельзя зарегистрироваться?</summary><p>Сервис проходит закрытое тестирование. Новых участников приглашает команда проекта. Публичной регистрации и активации кодов на этой странице нет.</p></details><details><summary>Когда откроется сервис?</summary><p>Дата общего запуска пока не объявлена. Сначала проверяем основной сценарий и собираем обратную связь участников.</p></details></div></div>'''

def invite(name, title, body='Сейчас собираем небольшой круг участников, чтобы проверить комнаты, видеоссылки и синхронизацию. Новых участников приглашает команда.'):
    return f'''<section class="invitation" id="access"><div><h2>{title}</h2><p>{body}</p></div><div class="invite-action"><details id="invite"><summary>У меня есть приглашение {ARROW}</summary><p>Откройте персональную ссылку, которую прислала команда {escape(name)}. На этом лендинге нет формы входа или регистрации.</p></details><p class="access-note">Закрытое тестирование · только по приглашению</p></div></section>'''

def narrative(title, text, secondtitle, secondtext):
    return f'<section class="narrative"><h2>{title}</h2><div><h3>{secondtitle}</h3><p>{text}</p><p>{secondtext}</p></div></section>'

