def content(b):
    name, s = b['name'], b['slug']
    if s == 'linkroom':
        return f'''<section class="link-hero wrap"><div><h1>Кидайте ссылку.<br>Собирайте<br><em>своих.</em></h1><p>То самое видео из Telegram. Большой разговор с YouTube. Всё, что хочется посмотреть не в одиночку.</p>{cta('Познакомиться с Линкрум')}<span class="under-cta">Общий просмотр. Личная комната.</span></div><div class="link-app"><div class="app-toolbar"><span class="window-dots"><i></i><i></i><i></i></span><span>Вечер, который мы собрали</span><span>↗</span></div>{player(s,title='Начнём с чего-нибудь красивого')}<div class="link-queue"><span>Откуда смотрим?</span>{sources()}</div>{demo_note()}</div></section><section class="link-statement" id="about"><div class="wrap"><h2>Ссылка есть.<br>План на вечер — тоже.</h2><p>Мы работаем над простым способом смотреть видео вместе: одна ссылка, одна комната, общий момент. От короткого ролика до разговора на весь вечер.</p></div></section><section class="link-steps wrap"><article><b>Вставить</b><p>Видео из привычного сервиса, которое хочется показать друзьям.</p></article><article><b>Позвать</b><p>Только свой круг. По личному приглашению в комнату.</p></article><article><b>Разделить</b><p>Просмотр в одном ритме и обсуждение прямо по ходу.</p></article></section><div class="wrap">{invite(name,'Встречаемся<br>в закрытом тесте.')}{faq(name)}</div>'''
    if s == 'titry':
        return f'''<section class="titry-hero wrap"><h1>Всё начинается<br>с <em>«посмотри это».</em></h1><div class="titry-intro"><p>Небольшое пространство для больших впечатлений.<br>Видео по ссылке, люди по любви.</p>{cta('Заглянуть в киноклуб')}</div><div class="titry-spread"><div>{player(s,title='После заката — ещё одна история')}{demo_note()}</div><aside><span class="vertical-word">ТИТРЫ</span><h2>Не откладывайте<br>разговор<br>до финальных<br>титров.</h2><p>Отправьте ролик из YouTube, Telegram или другой соцсети. А потом просто побудьте вместе.</p></aside></div></section><section class="titry-story wrap" id="about"><h2>Истории становятся<br>больше, когда ими<br><em>делятся.</em></h2><div><p>Вы наверняка пересылаете друг другу видео. «Титры» задуманы для следующего шага: не только отправить ссылку, но и посмотреть её вместе.</p><p>В закрытом тесте собираем личные комнаты, общий play и пространство для разговора.</p>{sources()}</div></section><div class="wrap">{invite(name,'Для своих.<br>Пока — буквально.')}{faq(name)}</div>'''
    if s == 'volna':
        return f'''<section class="volna-hero"><div class="wrap"><h1>Поймайте<br><em>общую волну.</em></h1><div class="volna-description"><p>Любой ролик может стать вашим вечером.<br>YouTube, Telegram и видео из соцсетей —<br>смотрите то, чем хочется поделиться.</p>{cta('На борт закрытого теста')}</div></div><div class="volna-screen">{player(s,title='По ту сторону привычного')}{demo_note()}</div></section><section class="volna-sources wrap" id="about"><h2>Разные источники.<br>Один поток впечатлений.</h2>{sources()}<div class="volna-line"><span>Ваш экран</span><div></div><b data-clock>00:00</b><div></div><span>Их экран</span></div><p>Мы создаём комнаты, в которых паузы, разговоры и неожиданные моменты случаются одновременно. Проверьте переключение источников в демонстрации выше.</p></section><div class="wrap">{invite(name,'Подключайтесь<br>на своей волне.')}{faq(name)}</div>'''
    if s == 'kadr':
        return f'''<section class="kadr-hero wrap"><div class="kadr-masthead"><h1>КАДР<span>↗</span></h1><div><p>Ваши видео.<br>Ваши люди.<br>Общий момент.</p>{cta('Получить доступ?')}</div></div><div class="kadr-grid"><aside><h2>Смотрим<br>то, что<br>пересылаем.</h2>{sources()}<p>Сервис совместного просмотра по ссылке. Сейчас в закрытом тестировании.</p></aside><div>{player(s,title='Новый взгляд на знакомый мир')}{demo_note()}</div></div></section><section class="kadr-editorial wrap" id="about"><h2>Сохранённое.<br>Пересланное.<br><em>Разделённое.</em></h2><div><p>У каждого есть папка с видео «на потом». А если «потом» устроить сегодня — и позвать своих?</p><p>Проверяем просмотр ссылок из YouTube, Telegram и других видеоплатформ. Строим приватные комнаты, в которых можно быть на одной секунде.</p><a class="plain-link" href="#access">О закрытом тестировании {ARROW}</a></div></section><div class="wrap">{invite(name,'Попадите<br>в первый кадр.')}{faq(name)}</div>'''
    if s == 'pled':
        return f'''<section class="pled-hero wrap"><div class="pled-type"><h1>Плед один.<br><em>Города разные.</em></h1><p>Соберите уютный вечер из любимых людей и видео, которое давно хотелось им показать.</p>{cta('Устроиться поудобнее')}</div><div class="pled-picture">{photo(s,alt='Тёплая атмосфера домашнего вечера')}<span class="pled-sticker">место<br>для своих</span><span class="pled-caption">Планы на вечер: никуда не спешить.</span></div></section><section class="pled-letter wrap" id="about"><h2>«Я тебе сейчас<br>такое покажу...»</h2><div><p>С этой фразы начинаются самые хорошие вечера. Мы делаем место, где можно открыть ссылку из Telegram или YouTube и посмотреть её вместе, даже если вы далеко.</p>{sources()}<p>Здесь всё строится вокруг вашей компании: своя комната, общий просмотр и разговор без спешки.</p></div></section><section class="pled-demo wrap"><div><h2>Своё место<br>по эту сторону экрана.</h2><p>Пример того, как может выглядеть ваша комната.</p></div><div>{player(s,title='Вечер с хорошим продолжением')}{demo_note()}</div></section><div class="wrap">{invite(name,'Круг пока небольшой.<br>И очень тёплый.')}{faq(name)}</div>'''
    if s == 'sync':
        return f'''<section class="sync-hero wrap"><div class="sync-top"><h1>БЕЗ «ТРИ,<br>ДВА, <em>ОДИН».</em></h1><div><p>Вы просто хотите посмотреть видео вместе.<br>А не выяснять, кто на какой секунде.</p>{cta('Попасть в тест')}</div></div><div class="sync-timers" aria-label="Демонстрация общей позиции"><div><span>Ваш экран</span><b data-clock>00:00</b></div><span class="sync-equal">=</span><div><span>Экран друга</span><b data-clock>00:00</b></div><span class="sync-equal">=</span><div><span>Общий момент</span><b data-clock>00:00</b></div></div>{player(s,'sync-panorama','Пауза тоже бывает общей')}{demo_note()}</section><section class="sync-links wrap" id="about"><h2>ОДНА ССЫЛКА.<br><em>ОБЩИЙ PLAY.</em></h2><div><p>Видео из YouTube. Находка из Telegram. Ролик из соцсети. Делаем так, чтобы поделиться означало ещё и посмотреть вместе.</p>{sources()}<p class="small-copy">Нажмите play в демонстрации: все три счётчика будут идти в одном ритме. Это локальный пример синхронизации.</p></div></section><div class="wrap">{invite(name,'ПРОВЕРИМ<br>В ОДНОМ РИТМЕ?')}{faq(name)}</div>'''
    if s == 'dubl':
        return f'''<section class="dubl-hero wrap"><div class="dubl-title"><h1>Кино на двоих.<br><em>Даже издалека.</em></h1><p>Пока между вами километры,<br>пусть хотя бы вечер будет общим.</p>{cta('О встрече в закрытом тесте')}</div><div class="dubl-screens"><div class="dubl-first">{player(s,title='Тот самый вечер')}{demo_note()}</div><div class="dubl-second">{photo(s)}<span>Другой экран. Тот же момент.</span><div><span data-clock>00:00</span><b>В одном ритме</b></div></div></div></section><section class="dubl-letter wrap" id="about"><span class="dubl-sign" aria-hidden="true">↗↙</span><h2>Одна ссылка —<br>ещё один повод<br><em>быть ближе.</em></h2><div><p>Переслать видео — хорошо. Увидеть реакцию любимого человека в тот же момент — ещё лучше. Мы работаем над личным пространством для таких встреч.</p><p>YouTube, Telegram и другие видеоссылки. Выбирайте историю под ваше настроение.</p>{sources()}</div></section><div class="wrap">{invite(name,'Место на двоих.<br>По приглашению.')}{faq(name)}</div>'''
    if s == 'komnata':
        return f'''<section class="komnata-hero">{photo(s,alt='Тихий пейзаж у воды')}<div class="komnata-shade"></div><div class="wrap"><h1>Ваш маленький<br><em>вечерний ритуал.</em></h1><p>Оставьте шум дня снаружи.<br>Здесь только ваше видео и ваши люди.</p>{cta('Заглянуть в Комнату')}<span class="komnata-foot">Одна ссылка. Свой круг. Никакой спешки.</span></div></section><section class="komnata-story wrap" id="about"><h2>Есть вещи,<br>которые лучше<br><em>смотреть вместе.</em></h2><div><p>Длинное интервью. Видео из канала в Telegram. Тот самый ролик с YouTube, который хочется обсудить.</p><p>«Комната» — проект сервиса для совместного просмотра по ссылке. Мы собираем спокойное пространство с приватными комнатами, синхронизацией и разговором рядом.</p>{sources()}</div></section><section class="komnata-demo wrap"><h2>Так может начаться<br>ваш следующий вечер.</h2>{player(s,title='Побудем здесь ещё немного')}{demo_note()}</section><div class="wrap">{invite(name,'Дверь пока<br>для приглашённых.')}{faq(name)}</div>'''
    if s == 'kruzhok':
        return f'''<section class="kruzhok-hero wrap"><div><h1>Весь интернет.<br>В своём <em>кружке.</em></h1><p>Ваши любимые люди, смешные видео, разговоры до ночи. Сделаем из пересланных ссылок общий вечер?</p>{cta('О маленьком закрытом клубе')}<div class="kruzhok-members" aria-label="Иллюстрация компании"><span>А</span><span>М</span><span>Д</span><b>У каждого свой экран.<br>Компания — одна.</b></div></div><div class="kruzhok-collage">{photo(s,alt='Атмосфера встречи в дружеской компании')}<span class="kruzhok-label">встречаемся<br>в интернете</span><span class="kruzhok-orbit" aria-hidden="true"></span></div></section><section class="kruzhok-links wrap" id="about"><h2>Не просто<br>«глянь ссылку».<br><em>А «давай вместе».</em></h2><div>{sources()}<p>Сохраняем привычный способ находить видео: YouTube, Telegram, соцсети. И добавляем то, чего не хватает в пересылке — общий просмотр и живой разговор.</p></div></section><section class="kruzhok-example wrap"><div>{player(s,title='История для вашего кружка')}{demo_note()}</div><aside><h2>Маленький круг.<br>Большой вечер.</h2><p>Приватные комнаты без случайных зрителей. Общая пауза, если кто-то пошёл за чаем. Реакции, которые не надо пересказывать.</p></aside></section><div class="wrap">{invite(name,'Берём в кружок.<br>Пока по приглашению.')}{faq(name)}</div>'''
    return f'''<section class="smotrim-hero wrap"><h1>Смотрите то,<br>что <em>пересылаете.</em></h1><div class="smotrim-intro"><p>Из лички — в общую комнату.<br>Ссылки из YouTube, Telegram и соцсетей для ваших вечеров вместе.</p>{cta('Открыть приглашение')}</div><div class="smotrim-browser"><div class="smotrim-tabs"><span class="browser-active">Ваш вечер</span><span>Одна компания</span><span>Общий просмотр</span></div><div class="smotrim-toolbar"><span>↶</span><span>⌂</span><span class="browser-url">smotrim / комната / вечер-для-своих</span><span>···</span></div><div class="smotrim-workspace"><aside><h2>Что посмотрим?</h2>{sources('queue-picker')}<p>Выберите источник<br>в демонстрации.</p></aside><div>{player(s,title='Ещё одна история, которую хочется разделить')}{demo_note()}</div></div></div></section><section class="smotrim-summary wrap" id="about"><h2>Переслать —<br>только начало.</h2><p>Мы делаем следующий шаг: общую комнату для видеоссылок. Чтобы не спрашивать «уже посмотрел?», а смеяться, удивляться и обсуждать одновременно.</p><div class="smotrim-verbs"><span>Нашли.</span><span>Позвали.</span><span>Смотрим.</span></div></section><div class="wrap">{invite(name,'Следующая вкладка —<br>закрытый тест.')}{faq(name)}</div>'''

def brand_page(index, assets):
    b = BRANDS[index - 1]
    title = f"{b['name']} — смотрите видео по ссылке вместе"
    html = f'''<!doctype html><html lang="ru" class="brand-{b['slug']}" style="--bg:{b['bg']};--fg:{b['fg']};--accent:{b['accent']}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{escape(b['tag'])} Совместный просмотр видео из YouTube, Telegram и других платформ. Закрытое тестирование, вход по приглашению."><meta name="theme-color" content="{b['bg']}"><title>{title}</title><link rel="icon" href="__ASSETS__brands/{b['slug']}.svg"><link rel="stylesheet" href="__ASSETS__brands.css"><script defer src="__ASSETS__brands.js"></script></head><body><a class="skip" href="#main">К содержимому</a>{header(b['name'],b['slug'])}<main id="main">{content(b)}</main><footer class="brand-footer wrap"><a href="#" class="footer-name">{b['name']}</a><span>Ваши видео. Ваши люди.</span><span>© 2026 · Закрытое тестирование</span></footer></body></html>'''
    return html.replace('__ASSETS__', assets).replace('<span>Ваши видео. Ваши люди.</span>',f'<span>{escape(b["tag"])}</span>')
